-- PidginCore schema baseline.
-- Generated by scripts/build-core-baseline.mjs from server/migrations. Do not edit by hand.
-- Creates the tables that server/src/core reads or writes, with their indexes and triggers,
-- for a fresh self-hosted install. The hosted edition's own migration history stays in its own folder.

CREATE TABLE agent_board_caps (
  board_kind TEXT PRIMARY KEY CHECK (board_kind IN ('project', 'commons', 'work')),
  posts_per_day INTEGER NOT NULL,
  bytes_per_day INTEGER NOT NULL,
  author_posts_per_day INTEGER NOT NULL,
  author_bytes_per_day INTEGER NOT NULL,
  people_reserve_posts INTEGER NOT NULL,
  people_reserve_bytes INTEGER NOT NULL
);

CREATE TABLE agent_board_digest_ai_worker_budget (
  day TEXT PRIMARY KEY,
  reserved_micro_usd INTEGER NOT NULL DEFAULT 0 CHECK (reserved_micro_usd BETWEEN 0 AND 1000000),
  attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0)
);

CREATE TABLE agent_work_board_caps (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  per_team INTEGER NOT NULL,
  per_agent INTEGER NOT NULL,
  per_parent INTEGER NOT NULL,
  default_ttl_days INTEGER NOT NULL,
  max_ttl_days INTEGER NOT NULL,
  idle_days INTEGER NOT NULL,
  delete_after_days INTEGER NOT NULL
);

CREATE TABLE artifact_upload_attempts (
  id TEXT PRIMARY KEY,
  owner TEXT NOT NULL,
  artifact_id TEXT NOT NULL,
  version INTEGER NOT NULL,
  r2_key TEXT NOT NULL UNIQUE,
  size_bytes INTEGER NOT NULL,
  source_size INTEGER NOT NULL DEFAULT 0,
  state TEXT NOT NULL CHECK(state IN ('staging','retired')),
  created_ms INTEGER NOT NULL
);

CREATE INDEX artifact_upload_cleanup ON artifact_upload_attempts(state,created_ms);

CREATE TABLE audio_items (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  title TEXT NOT NULL DEFAULT 'Untitled audio',
  kind TEXT NOT NULL CHECK (kind IN ('upload', 'narration')),
  mode TEXT CHECK (mode IS NULL OR mode IN ('full', 'summary')),
  status TEXT NOT NULL DEFAULT 'processing'
    CHECK (status IN ('processing', 'ready', 'failed', 'transcript_only')),
  error TEXT,
  mime TEXT,
  size_bytes INTEGER,
  duration_seconds INTEGER,
  estimated_seconds INTEGER,
  source_words INTEGER,
  script_words INTEGER,
  provider TEXT,
  voice TEXT,
  model TEXT,
  source_message_id TEXT,
  audio_key TEXT,
  transcript_key TEXT,
  source_key TEXT,
  storage_bytes INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE INDEX idx_audio_items_user_created ON audio_items(user_id, created_at);

CREATE TABLE client_builds (
  platform TEXT PRIMARY KEY,
  latest_build INTEGER NOT NULL,
  latest_version TEXT,
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE design_systems (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  name TEXT NOT NULL,
  display_name TEXT NOT NULL,
  description TEXT,
  tokens_json TEXT NOT NULL,
  css TEXT,
  source TEXT NOT NULL DEFAULT 'custom',
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE UNIQUE INDEX idx_design_systems_user_name ON design_systems(user_id, name);

CREATE TABLE destination_configs (
  name TEXT PRIMARY KEY,
  value TEXT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE doc_access_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  doc_id TEXT NOT NULL,
  event TEXT NOT NULL,
  ip TEXT,
  user_agent TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX idx_doc_access_created ON doc_access_log(created_at DESC);

CREATE INDEX idx_doc_access_doc ON doc_access_log(doc_id);

CREATE TABLE document_audience_audit (
 id TEXT PRIMARY KEY, team_id TEXT NOT NULL, user_id TEXT NOT NULL,
 action TEXT NOT NULL, details TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT(datetime('now'))
);

CREATE TRIGGER document_audience_audit_no_delete BEFORE DELETE ON document_audience_audit
BEGIN SELECT RAISE(ABORT,'Document audience audit is append-only'); END;

CREATE TRIGGER document_audience_audit_no_update BEFORE UPDATE ON document_audience_audit
BEGIN SELECT RAISE(ABORT,'Document audience audit is append-only'); END;

CREATE TABLE oauth_legacy_consumed (
  token_hash TEXT PRIMARY KEY,
  expires_at INTEGER NOT NULL
);

CREATE TABLE governed_content_cleanup (
  id TEXT PRIMARY KEY,
  resource_type TEXT NOT NULL CHECK(resource_type IN ('document','artifact','hosted_account')),
  resource_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  object_keys TEXT NOT NULL CHECK(json_valid(object_keys)),
  storage_bytes INTEGER NOT NULL CHECK(storage_bytes>=0),
  created_at TEXT NOT NULL DEFAULT(datetime('now'))
, usage_releases TEXT
  CHECK (usage_releases IS NULL OR json_valid(usage_releases)));

CREATE TABLE help_usage (
  scope TEXT NOT NULL,
  day TEXT NOT NULL,
  count INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (scope, day)
);

CREATE TABLE users (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  email TEXT UNIQUE NOT NULL,
  invited_by TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  status TEXT NOT NULL DEFAULT 'active'
);

CREATE TRIGGER account_primary_insert BEFORE INSERT ON users
WHEN EXISTS(SELECT 1 FROM user_identities WHERE lower(email)=lower(NEW.email) AND user_id<>NEW.id)
 OR EXISTS(SELECT 1 FROM google_identities WHERE lower(email)=lower(NEW.email) AND user_id<>NEW.id)
BEGIN SELECT RAISE(ABORT, 'Email belongs to another account'); END;

CREATE TRIGGER account_primary_update BEFORE UPDATE OF email ON users
WHEN EXISTS(SELECT 1 FROM user_identities WHERE lower(email)=lower(NEW.email) AND user_id<>NEW.id)
 OR EXISTS(SELECT 1 FROM google_identities WHERE lower(email)=lower(NEW.email) AND user_id<>NEW.id)
BEGIN SELECT RAISE(ABORT, 'Email belongs to another account'); END;

CREATE TABLE api_keys (
  key_hash TEXT PRIMARY KEY,
  key_prefix TEXT NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  label TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  last_used_at TEXT
);

CREATE INDEX idx_api_keys_user_id ON api_keys(user_id);

CREATE TABLE artifact_embed_events (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id TEXT NOT NULL REFERENCES users(id),
  message_id TEXT NOT NULL,
  artifact_id TEXT NOT NULL,
  event TEXT NOT NULL CHECK (event IN ('loaded', 'failed', 'opened_fullscreen')),
  duration_ms INTEGER,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX idx_artifact_embed_events_created
  ON artifact_embed_events(user_id, created_at DESC);

CREATE TABLE audit_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  action TEXT NOT NULL,
  instance_id TEXT,
  details TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, user_id TEXT REFERENCES users(id));

CREATE INDEX idx_audit_created ON audit_log(created_at DESC);

CREATE TABLE conversations (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id),
  instance_session_id TEXT,
  instance_project TEXT,
  title TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'open',
  last_poll_at TEXT,
  -- Stamped at close (+30 days); the daily expiry cron hard-deletes the
  -- conversation and its messages/bindings after that, mirroring the
  -- migration-0013 cold-storage pattern.
  expires_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  last_activity_at TEXT NOT NULL DEFAULT (datetime('now'))
, doc_id TEXT);

CREATE INDEX idx_conversations_doc ON conversations(doc_id) WHERE doc_id IS NOT NULL;

CREATE INDEX idx_conversations_user ON conversations(user_id, status, last_activity_at);

CREATE TABLE device_tokens (
  token TEXT PRIMARY KEY,
  platform TEXT NOT NULL DEFAULT 'ios',
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, user_id TEXT REFERENCES users(id), bundle_id TEXT, apns_environment TEXT
  CHECK (apns_environment IS NULL OR apns_environment IN ('sandbox','production')));

CREATE INDEX idx_device_tokens_platform ON device_tokens(platform);

CREATE INDEX idx_device_tokens_user_id ON device_tokens(user_id);

CREATE TABLE device_logins (
  device_hash TEXT PRIMARY KEY,
  user_code_hash TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'denied')),
  user_id TEXT REFERENCES users(id) ON DELETE CASCADE,
  csrf_hash TEXT,
  session_hash TEXT,
  last_poll_at INTEGER NOT NULL DEFAULT 0,
  expires_at INTEGER NOT NULL
);

CREATE INDEX idx_device_login_expiry ON device_logins(expires_at);

CREATE TABLE entra_identities (
  tenant_id TEXT NOT NULL,
  object_id TEXT NOT NULL,
  user_id TEXT NOT NULL UNIQUE REFERENCES users(id),
  principal_name TEXT NOT NULL,
  display_name TEXT NOT NULL,
  last_login_at TEXT,
  PRIMARY KEY (tenant_id, object_id)
);

CREATE TRIGGER account_entra_insert BEFORE INSERT ON entra_identities
WHEN EXISTS(SELECT 1 FROM users WHERE lower(email)=lower(NEW.principal_name) AND id<>NEW.user_id)
 OR EXISTS(SELECT 1 FROM user_identities WHERE lower(email)=lower(NEW.principal_name) AND user_id<>NEW.user_id)
 OR EXISTS(SELECT 1 FROM google_identities WHERE lower(email)=lower(NEW.principal_name) AND user_id<>NEW.user_id)
BEGIN SELECT RAISE(ABORT, 'Email belongs to another account'); END;

CREATE TRIGGER account_entra_update BEFORE UPDATE OF principal_name,user_id ON entra_identities
WHEN EXISTS(SELECT 1 FROM users WHERE lower(email)=lower(NEW.principal_name) AND id<>NEW.user_id)
 OR EXISTS(SELECT 1 FROM user_identities WHERE lower(email)=lower(NEW.principal_name) AND user_id<>NEW.user_id)
 OR EXISTS(SELECT 1 FROM google_identities WHERE lower(email)=lower(NEW.principal_name) AND user_id<>NEW.user_id)
BEGIN SELECT RAISE(ABORT, 'Email belongs to another account'); END;

CREATE TABLE entra_sessions (
  token_hash TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id),
  expires_at INTEGER NOT NULL
);

CREATE INDEX idx_entra_sessions_expiry ON entra_sessions(expires_at);

CREATE TABLE "google_identities" (
  subject TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id),
  email TEXT NOT NULL,
  hosted_domain TEXT NOT NULL,
  display_name TEXT NOT NULL,
  last_login_at TEXT
);

CREATE UNIQUE INDEX idx_google_identities_email ON google_identities(email COLLATE NOCASE);

CREATE INDEX idx_google_identities_hosted_domain ON google_identities(hosted_domain);

CREATE INDEX idx_google_identities_user ON google_identities(user_id);

CREATE TRIGGER account_google_insert BEFORE INSERT ON google_identities
WHEN EXISTS(SELECT 1 FROM users WHERE lower(email)=lower(NEW.email) AND id<>NEW.user_id)
 OR EXISTS(SELECT 1 FROM user_identities WHERE lower(email)=lower(NEW.email) AND user_id<>NEW.user_id)
 OR EXISTS(SELECT 1 FROM entra_identities WHERE lower(principal_name)=lower(NEW.email) AND user_id<>NEW.user_id)
BEGIN SELECT RAISE(ABORT, 'Email belongs to another account'); END;

CREATE TRIGGER account_google_owner BEFORE UPDATE OF user_id ON google_identities
WHEN OLD.user_id<>NEW.user_id
BEGIN SELECT RAISE(ABORT, 'Google account belongs to another user'); END;

CREATE TRIGGER account_google_update BEFORE UPDATE OF email,user_id ON google_identities
WHEN EXISTS(SELECT 1 FROM users WHERE lower(email)=lower(NEW.email) AND id<>NEW.user_id)
 OR EXISTS(SELECT 1 FROM user_identities WHERE lower(email)=lower(NEW.email) AND user_id<>NEW.user_id)
 OR EXISTS(SELECT 1 FROM entra_identities WHERE lower(principal_name)=lower(NEW.email) AND user_id<>NEW.user_id)
BEGIN SELECT RAISE(ABORT, 'Email belongs to another account'); END;

CREATE TABLE google_sessions (
  token_hash TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id),
  expires_at INTEGER NOT NULL
, google_subject TEXT);

CREATE INDEX idx_google_sessions_expiry ON google_sessions(expires_at);

CREATE TABLE instances (
  instance_id TEXT PRIMARY KEY,
  model TEXT NOT NULL,
  project TEXT NOT NULL,
  working_on TEXT,
  source TEXT NOT NULL,
  registered_at TEXT NOT NULL DEFAULT (datetime('now')),
  last_heartbeat TEXT NOT NULL DEFAULT (datetime('now'))
, user_id TEXT REFERENCES users(id));

CREATE TABLE managed_sessions (
  token_hash TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id),
  expires_at INTEGER NOT NULL
);

CREATE INDEX managed_session_expiry ON managed_sessions(expires_at);

CREATE TABLE teams (
  id TEXT PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  owner_user_id TEXT NOT NULL REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TRIGGER team_governance_no_team_delete BEFORE DELETE ON teams
WHEN EXISTS(SELECT 1 FROM team_governance WHERE team_id=OLD.id)
BEGIN SELECT RAISE(ABORT, 'Governed teams require a reviewed deletion process'); END;

CREATE TABLE "user_favorites" (
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('doc', 'artifact', 'message', 'runbook', 'audio')),
  item_id TEXT NOT NULL,
  title TEXT NOT NULL DEFAULT '',
  team_id TEXT,
  position INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (user_id, kind, item_id)
);

CREATE INDEX idx_user_favorites_order ON user_favorites(user_id, position);

CREATE TABLE user_identities (
  email TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  provider TEXT NOT NULL,
  provider_sub TEXT,
  created_at TEXT DEFAULT (datetime('now'))
);

CREATE UNIQUE INDEX idx_user_identities_email_nocase ON user_identities(email COLLATE NOCASE);

CREATE INDEX idx_user_identities_user_id ON user_identities(user_id);

CREATE TRIGGER account_alias_insert BEFORE INSERT ON user_identities
WHEN EXISTS(SELECT 1 FROM users WHERE lower(email)=lower(NEW.email) AND id<>NEW.user_id)
 OR EXISTS(SELECT 1 FROM user_identities WHERE lower(email)=lower(NEW.email) AND user_id<>NEW.user_id)
 OR EXISTS(SELECT 1 FROM google_identities WHERE lower(email)=lower(NEW.email) AND user_id<>NEW.user_id)
 OR EXISTS(SELECT 1 FROM entra_identities WHERE lower(principal_name)=lower(NEW.email) AND user_id<>NEW.user_id)
BEGIN SELECT RAISE(ABORT, 'Email belongs to another account'); END;

CREATE TRIGGER account_alias_update BEFORE UPDATE OF email,user_id ON user_identities
WHEN EXISTS(SELECT 1 FROM users WHERE lower(email)=lower(NEW.email) AND id<>NEW.user_id)
 OR EXISTS(SELECT 1 FROM user_identities WHERE lower(email)=lower(NEW.email) AND user_id<>NEW.user_id)
 OR EXISTS(SELECT 1 FROM google_identities WHERE lower(email)=lower(NEW.email) AND user_id<>NEW.user_id)
 OR EXISTS(SELECT 1 FROM entra_identities WHERE lower(principal_name)=lower(NEW.email) AND user_id<>NEW.user_id)
BEGIN SELECT RAISE(ABORT, 'Email belongs to another account'); END;

CREATE TABLE user_settings (
  user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  commute_source TEXT NOT NULL DEFAULT 'latest'
    CHECK (commute_source IN ('latest', 'playlist')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE agent_board_digest_ai_attempts (
  id TEXT PRIMARY KEY,
  team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  day TEXT NOT NULL,
  project_id TEXT NOT NULL,
  scope TEXT NOT NULL CHECK (scope IN ('bulletin', 'handoffs')),
  window_start TEXT NOT NULL,
  source_count INTEGER NOT NULL CHECK (source_count BETWEEN 1 AND 8),
  prompt_bytes INTEGER NOT NULL CHECK (prompt_bytes > 0),
  max_output_tokens INTEGER NOT NULL CHECK (max_output_tokens > 0),
  reserved_micro_usd INTEGER NOT NULL CHECK (reserved_micro_usd BETWEEN 1 AND 250000),
  model TEXT NOT NULL,
  prompt_version TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'reserved' CHECK (status IN ('reserved', 'failed', 'committed')),
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX idx_agent_board_digest_ai_attempts_team_day ON agent_board_digest_ai_attempts(team_id, day, created_at);

CREATE TRIGGER agent_board_digest_ai_reserve BEFORE INSERT ON agent_board_digest_ai_attempts
BEGIN
  SELECT RAISE(ABORT, 'board_digest_ai_budget') WHERE
    NEW.reserved_micro_usd + COALESCE((SELECT reserved_micro_usd FROM agent_board_digest_ai_budget
      WHERE team_id = NEW.team_id AND day = NEW.day), 0) > 250000
    OR COALESCE((SELECT attempts FROM agent_board_digest_ai_budget
      WHERE team_id = NEW.team_id AND day = NEW.day), 0) >= 150;
  SELECT RAISE(ABORT, 'board_digest_ai_worker_budget') WHERE
    NEW.reserved_micro_usd + COALESCE((SELECT reserved_micro_usd FROM agent_board_digest_ai_worker_budget
      WHERE day = NEW.day), 0) > 1000000;
  INSERT INTO agent_board_digest_ai_worker_budget(day,reserved_micro_usd,attempts)
    VALUES (NEW.day,NEW.reserved_micro_usd,1)
    ON CONFLICT(day) DO UPDATE SET
      reserved_micro_usd=reserved_micro_usd+excluded.reserved_micro_usd,
      attempts=attempts+1;
  INSERT INTO agent_board_digest_ai_budget(team_id, day, reserved_micro_usd, attempts)
    VALUES (NEW.team_id, NEW.day, NEW.reserved_micro_usd, 1)
    ON CONFLICT(team_id, day) DO UPDATE SET
      reserved_micro_usd = reserved_micro_usd + excluded.reserved_micro_usd,
      attempts = attempts + 1;
END;

CREATE TABLE agent_board_digest_ai_budget (
  team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  day TEXT NOT NULL,
  reserved_micro_usd INTEGER NOT NULL DEFAULT 0 CHECK (reserved_micro_usd BETWEEN 0 AND 250000),
  attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts BETWEEN 0 AND 150),
  PRIMARY KEY (team_id, day)
);

CREATE TABLE agent_board_digest_team_state (
  team_id TEXT PRIMARY KEY REFERENCES teams(id) ON DELETE CASCADE,
  last_attempt_at TEXT NOT NULL,
  selected_count INTEGER NOT NULL DEFAULT 1
);

CREATE TABLE agent_board_digests (
  id TEXT PRIMARY KEY,
  team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  -- Plain text keeps a historical digest when an archived work board is deleted.
  project_id TEXT NOT NULL,
  project_name TEXT NOT NULL,
  scope TEXT NOT NULL CHECK (scope IN ('bulletin', 'handoffs')),
  window_start TEXT NOT NULL,
  window_end TEXT NOT NULL,
  part INTEGER NOT NULL CHECK (part >= 0),
  summary TEXT NOT NULL,
  provider TEXT NOT NULL,
  model TEXT NOT NULL,
  covered_count INTEGER NOT NULL CHECK (covered_count > 0),
  source_first_seq INTEGER NOT NULL,
  source_last_seq INTEGER NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')), prompt_version TEXT, reserved_micro_usd INTEGER, ai_attempt_id TEXT,
  UNIQUE(team_id, project_id, scope, window_start, part)
);

CREATE UNIQUE INDEX idx_agent_board_digests_ai_attempt ON agent_board_digests(ai_attempt_id) WHERE ai_attempt_id IS NOT NULL;

CREATE INDEX idx_agent_board_digests_list ON agent_board_digests(team_id, scope, project_id, window_start DESC, part DESC, id DESC);

CREATE TABLE agent_identities (
  id TEXT PRIMARY KEY,
  team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  slug TEXT NOT NULL,
  name TEXT NOT NULL,
  provider TEXT,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'revoked')),
  created_by_user_id TEXT NOT NULL REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  revoked_at TEXT, self_minted INTEGER NOT NULL DEFAULT 0 CHECK (self_minted IN (0, 1)), kind TEXT NOT NULL DEFAULT 'agent' CHECK (kind IN ('agent', 'person')), signin_connected INTEGER NOT NULL DEFAULT 0 CHECK (signin_connected IN (0, 1)),
  UNIQUE(team_id, slug)
);

CREATE UNIQUE INDEX idx_agent_identities_person ON agent_identities(team_id, created_by_user_id) WHERE kind = 'person';

CREATE INDEX idx_agent_identities_sponsor
  ON agent_identities(team_id, created_by_user_id, self_minted, status);

CREATE INDEX idx_agent_identities_team ON agent_identities(team_id, status, slug);

CREATE TRIGGER oauth_agent_revoked AFTER UPDATE OF status ON agent_identities
WHEN NEW.status = 'revoked' BEGIN
  DELETE FROM oauth_refresh WHERE agent_id = NEW.id;
  UPDATE oauth_connections SET revoked_at = datetime('now') WHERE agent_id = NEW.id AND revoked_at IS NULL;
END;

CREATE TABLE chat_messages (
  id TEXT PRIMARY KEY,
  conversation_id TEXT NOT NULL REFERENCES conversations(id),
  sender TEXT NOT NULL CHECK (sender IN ('agent', 'user', 'system')),
  channel TEXT,
  body TEXT NOT NULL,
  external_event_id TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX idx_chat_messages_conv ON chat_messages(conversation_id, created_at);

CREATE UNIQUE INDEX idx_chat_messages_ext
  ON chat_messages(channel, external_event_id)
  WHERE external_event_id IS NOT NULL;

CREATE TABLE conversation_channels (
  conversation_id TEXT NOT NULL REFERENCES conversations(id),
  channel TEXT NOT NULL,
  external_id TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (conversation_id, channel)
);

CREATE UNIQUE INDEX idx_conversation_channels_ext ON conversation_channels(channel, external_id);

CREATE TABLE document_audience_preferences (
 team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
 user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 audience TEXT NOT NULL CHECK(audience IN ('private','team','role')),
 role_id TEXT,
 revision INTEGER NOT NULL CHECK(revision>0),
 PRIMARY KEY(team_id,user_id),
 CHECK((audience='role' AND role_id IS NOT NULL) OR (audience!='role' AND role_id IS NULL))
);

CREATE TABLE event_tickets (
  ticket_hash TEXT PRIMARY KEY,
  team_id TEXT REFERENCES teams(id) ON DELETE CASCADE,
  principal_ref TEXT NOT NULL,
  credential_hash TEXT NOT NULL,
  filter TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(filter)),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  expires_at TEXT NOT NULL,
  used_at TEXT
);

CREATE INDEX idx_event_tickets_expires ON event_tickets(expires_at);

CREATE INDEX idx_event_tickets_principal ON event_tickets(principal_ref, created_at);

CREATE TABLE event_usage (
  team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  day TEXT NOT NULL,
  events INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (team_id, day)
);

CREATE INDEX idx_event_usage_day ON event_usage(day);

CREATE TABLE personal_notes (
  id TEXT PRIMARY KEY,
  team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('paste', 'idea')),
  title TEXT NOT NULL DEFAULT '',
  body TEXT NOT NULL,
  pinned INTEGER NOT NULL DEFAULT 0 CHECK (pinned IN (0, 1)),
  archived_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX idx_personal_notes_team ON personal_notes(team_id);

CREATE INDEX idx_personal_notes_user_team ON personal_notes(user_id, team_id, pinned DESC, updated_at DESC, id DESC);

CREATE TABLE team_governance (
  team_id TEXT PRIMARY KEY REFERENCES teams(id) ON DELETE CASCADE,
  all_includes_guests INTEGER NOT NULL DEFAULT 1 CHECK(all_includes_guests IN (0,1)),
  revision INTEGER NOT NULL DEFAULT 1 CHECK(revision > 0),
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE team_memberships (
  team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role TEXT NOT NULL CHECK (role IN ('owner', 'admin', 'member', 'viewer')),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (team_id, user_id)
);

CREATE TRIGGER team_governance_membership_insert BEFORE INSERT ON team_memberships
WHEN EXISTS(SELECT 1 FROM team_governance WHERE team_id=NEW.team_id) AND NEW.role NOT IN ('member','viewer')
BEGIN SELECT RAISE(ABORT, 'New governed members must begin as users'); END;

CREATE TABLE workspace_tags (
  id TEXT PRIMARY KEY,
  team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  slug TEXT NOT NULL,
  name TEXT NOT NULL,
  color TEXT NOT NULL DEFAULT 'teal' CHECK (color IN ('teal','blue','amber','violet','rose')),
  created_by_user_id TEXT NOT NULL REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE(team_id, slug)
);

CREATE INDEX idx_workspace_tags_team ON workspace_tags(team_id, name);

CREATE TABLE agent_board_digest_entries (
  entry_id TEXT PRIMARY KEY,
  digest_id TEXT NOT NULL REFERENCES agent_board_digests(id) ON DELETE CASCADE,
  team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  project_id TEXT NOT NULL,
  source_seq INTEGER NOT NULL,
  created_at TEXT NOT NULL
);

CREATE INDEX idx_agent_board_digest_entries_digest ON agent_board_digest_entries(digest_id, source_seq);

CREATE INDEX idx_agent_board_digest_entries_team ON agent_board_digest_entries(team_id, project_id, source_seq);

CREATE TABLE agent_keys (
  key_hash TEXT PRIMARY KEY,
  key_prefix TEXT NOT NULL,
  agent_id TEXT NOT NULL REFERENCES agent_identities(id) ON DELETE CASCADE,
  created_by_user_id TEXT NOT NULL REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  last_used_at TEXT,
  revoked_at TEXT
);

CREATE INDEX idx_agent_keys_agent ON agent_keys(agent_id, revoked_at);

CREATE TRIGGER agent_keys_not_person BEFORE INSERT ON agent_keys
WHEN (SELECT kind FROM agent_identities WHERE id = NEW.agent_id) = 'person'
BEGIN
  SELECT RAISE(ABORT, 'person identities cannot hold agent keys');
END;

CREATE TABLE oauth_connections (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  client_id TEXT NOT NULL,
  client_name TEXT NOT NULL,
  team_id TEXT REFERENCES teams(id) ON DELETE CASCADE,
  agent_id TEXT REFERENCES agent_identities(id) ON DELETE CASCADE,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  last_refreshed_at TEXT,
  revoked_at TEXT,
  CHECK (agent_id IS NULL OR team_id IS NOT NULL)
);

CREATE INDEX idx_oauth_connections_user ON oauth_connections(user_id, client_id);

CREATE TABLE oauth_consents (
  request_hash TEXT PRIMARY KEY,
  csrf_hash TEXT NOT NULL,
  session_hash TEXT NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  client_id TEXT NOT NULL,
  redirect_uri TEXT NOT NULL,
  state TEXT NOT NULL,
  scope TEXT NOT NULL,
  code_challenge TEXT NOT NULL,
  expires_at INTEGER NOT NULL
, team_id TEXT REFERENCES teams(id) ON DELETE CASCADE, agent_id TEXT REFERENCES agent_identities(id) ON DELETE CASCADE);

CREATE INDEX idx_oauth_consent_expiry ON oauth_consents(expires_at);

CREATE TABLE projects (
  id TEXT PRIMARY KEY,
  team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  slug TEXT NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  created_by_user_id TEXT NOT NULL REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')), pinned INTEGER NOT NULL DEFAULT 0 CHECK (pinned IN (0, 1)), archived_at TEXT, board_kind TEXT NOT NULL DEFAULT 'project'
  CHECK (board_kind IN ('project', 'commons', 'work')), parent_project_id TEXT REFERENCES projects(id) ON DELETE CASCADE, created_by_agent_id TEXT REFERENCES agent_identities(id) ON DELETE SET NULL, expires_at TEXT, last_post_at TEXT,
  UNIQUE(team_id, slug)
);

CREATE INDEX idx_projects_created_by_agent ON projects(created_by_agent_id);

CREATE UNIQUE INDEX idx_projects_one_commons ON projects(team_id) WHERE board_kind = 'commons';

CREATE INDEX idx_projects_parent ON projects(parent_project_id);

CREATE INDEX idx_projects_team_kind ON projects(team_id, board_kind, archived_at);

CREATE TRIGGER projects_board_kind_immutable BEFORE UPDATE OF board_kind ON projects
WHEN NEW.board_kind IS NOT OLD.board_kind
  AND (OLD.board_kind IN ('work', 'commons') OR NEW.board_kind = 'work')
BEGIN
  SELECT RAISE(ABORT, 'cap:board_kind_immutable');
END;

CREATE TRIGGER projects_parent_fixed BEFORE UPDATE OF parent_project_id, team_id ON projects
WHEN NEW.parent_project_id IS NOT OLD.parent_project_id
  OR (OLD.board_kind = 'work' AND NEW.team_id IS NOT OLD.team_id)
BEGIN
  SELECT RAISE(ABORT, 'cap:work_board_parent');
END;

CREATE TRIGGER projects_parent_only_work BEFORE INSERT ON projects
WHEN NEW.board_kind <> 'work' AND NEW.parent_project_id IS NOT NULL
BEGIN
  SELECT RAISE(ABORT, 'cap:work_board_parent');
END;

CREATE TRIGGER projects_work_board_closed BEFORE UPDATE OF archived_at ON projects
WHEN OLD.board_kind = 'work' AND OLD.archived_at IS NOT NULL AND NEW.archived_at IS NULL
BEGIN
  SELECT RAISE(ABORT, 'cap:work_board_closed');
END;

CREATE TRIGGER projects_work_board_insert BEFORE INSERT ON projects
WHEN NEW.board_kind = 'work'
BEGIN
  SELECT RAISE(ABORT, 'cap:work_board_parent')
  WHERE NOT EXISTS (SELECT 1 FROM projects parent WHERE parent.id = NEW.parent_project_id
    AND parent.team_id = NEW.team_id AND parent.board_kind IN ('project', 'commons'));
  SELECT RAISE(ABORT, 'cap:work_boards_team')
  WHERE (SELECT COUNT(*) FROM projects WHERE team_id = NEW.team_id AND board_kind = 'work' AND archived_at IS NULL)
    >= (SELECT per_team FROM agent_work_board_caps WHERE id = 1);
  SELECT RAISE(ABORT, 'cap:work_boards_agent')
  WHERE (SELECT COUNT(*) FROM projects WHERE created_by_agent_id = NEW.created_by_agent_id
      AND board_kind = 'work' AND archived_at IS NULL)
    >= (SELECT per_agent FROM agent_work_board_caps WHERE id = 1);
  SELECT RAISE(ABORT, 'cap:work_boards_parent')
  WHERE (SELECT COUNT(*) FROM projects WHERE parent_project_id = NEW.parent_project_id
      AND board_kind = 'work' AND archived_at IS NULL)
    >= (SELECT per_parent FROM agent_work_board_caps WHERE id = 1);
END;

CREATE TABLE team_access_roles (
  id TEXT PRIMARY KEY,
  team_id TEXT NOT NULL REFERENCES team_governance(team_id) ON DELETE CASCADE,
  slug TEXT NOT NULL,
  name TEXT NOT NULL,
  kind TEXT NOT NULL CHECK(kind IN ('custom','company','all')),
  UNIQUE(team_id,id), UNIQUE(team_id,slug)
);

CREATE UNIQUE INDEX team_access_builtin ON team_access_roles(team_id,kind) WHERE kind!='custom';

CREATE TABLE workspace_resource_tags (
  team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  tag_id TEXT NOT NULL REFERENCES workspace_tags(id) ON DELETE CASCADE,
  resource_type TEXT NOT NULL CHECK (resource_type IN ('message','artifact')),
  resource_id TEXT NOT NULL,
  created_by_user_id TEXT NOT NULL REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (tag_id, resource_type, resource_id)
);

CREATE INDEX idx_workspace_resource_tags_resource ON workspace_resource_tags(team_id, resource_type, resource_id);

CREATE TABLE agent_board_author_usage (
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  agent_id TEXT NOT NULL REFERENCES agent_identities(id) ON DELETE CASCADE,
  day TEXT NOT NULL,
  posts INTEGER NOT NULL DEFAULT 0,
  bytes INTEGER NOT NULL DEFAULT 0, extended_inline_posts INTEGER NOT NULL DEFAULT 0
  CHECK (extended_inline_posts >= 0),
  PRIMARY KEY (project_id, agent_id, day)
);

CREATE INDEX idx_agent_board_author_usage_day ON agent_board_author_usage(day);

CREATE TRIGGER agent_board_author_usage_cap_insert BEFORE INSERT ON agent_board_author_usage
BEGIN
  SELECT RAISE(ABORT, 'cap:author_posts_day')
  WHERE NEW.posts > (SELECT c.author_posts_per_day FROM projects p JOIN agent_board_caps c ON c.board_kind = p.board_kind
    WHERE p.id = NEW.project_id);
  SELECT RAISE(ABORT, 'cap:author_bytes_day')
  WHERE NEW.bytes > (SELECT c.author_bytes_per_day FROM projects p JOIN agent_board_caps c ON c.board_kind = p.board_kind
    WHERE p.id = NEW.project_id);
  SELECT RAISE(ABORT, 'cap:board_people_reserve')
  WHERE (SELECT kind FROM agent_identities WHERE id = NEW.agent_id) = 'agent'
    AND EXISTS (SELECT 1 FROM agent_board_usage u JOIN projects p ON p.id = u.project_id
      JOIN agent_board_caps c ON c.board_kind = p.board_kind
      WHERE u.project_id = NEW.project_id AND u.day = NEW.day
        AND (u.posts > c.posts_per_day - c.people_reserve_posts OR u.bytes > c.bytes_per_day - c.people_reserve_bytes));
END;

CREATE TRIGGER agent_board_author_usage_cap_update BEFORE UPDATE ON agent_board_author_usage
WHEN NEW.posts > OLD.posts OR NEW.bytes > OLD.bytes
BEGIN
  SELECT RAISE(ABORT, 'cap:author_posts_day')
  WHERE NEW.posts > (SELECT c.author_posts_per_day FROM projects p JOIN agent_board_caps c ON c.board_kind = p.board_kind
    WHERE p.id = NEW.project_id);
  SELECT RAISE(ABORT, 'cap:author_bytes_day')
  WHERE NEW.bytes > (SELECT c.author_bytes_per_day FROM projects p JOIN agent_board_caps c ON c.board_kind = p.board_kind
    WHERE p.id = NEW.project_id);
  SELECT RAISE(ABORT, 'cap:board_people_reserve')
  WHERE (SELECT kind FROM agent_identities WHERE id = NEW.agent_id) = 'agent'
    AND EXISTS (SELECT 1 FROM agent_board_usage u JOIN projects p ON p.id = u.project_id
      JOIN agent_board_caps c ON c.board_kind = p.board_kind
      WHERE u.project_id = NEW.project_id AND u.day = NEW.day
        AND (u.posts > c.posts_per_day - c.people_reserve_posts OR u.bytes > c.bytes_per_day - c.people_reserve_bytes));
END;

CREATE TABLE agent_board_entries (
  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  id TEXT NOT NULL UNIQUE,
  team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  agent_id TEXT NOT NULL REFERENCES agent_identities(id),
  kind TEXT NOT NULL CHECK (kind IN ('s', 'c', 'h', 'd', 'b', 'n')),
  topic TEXT NOT NULL,
  body TEXT NOT NULL,
  reference TEXT,
  client_message_id TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')), user_id TEXT REFERENCES users(id), session_id TEXT, session_name TEXT, model TEXT, model_version TEXT, origin TEXT, origin_version TEXT, intent TEXT CHECK (intent IN ('question', 'answer')), reply_to_seq INTEGER, to_ref TEXT, to_auto INTEGER NOT NULL DEFAULT 0 CHECK (to_auto IN (0, 1)),
  UNIQUE(agent_id, project_id, client_message_id)
);

CREATE INDEX idx_agent_board_entries_compaction ON agent_board_entries(datetime(created_at), seq);

CREATE INDEX idx_agent_board_intent ON agent_board_entries(project_id, intent, seq);

CREATE INDEX idx_agent_board_project_seq ON agent_board_entries(project_id, seq);

CREATE INDEX idx_agent_board_reply ON agent_board_entries(project_id, reply_to_seq) WHERE reply_to_seq IS NOT NULL;

CREATE INDEX idx_agent_board_session
  ON agent_board_entries(project_id, agent_id, user_id, origin, session_id, seq);

CREATE INDEX idx_agent_board_team_created ON agent_board_entries(team_id, created_at DESC);

CREATE INDEX idx_agent_board_to ON agent_board_entries(project_id, to_ref, seq) WHERE to_ref IS NOT NULL;

CREATE INDEX idx_agent_board_to_recent ON agent_board_entries(to_ref, created_at) WHERE to_ref IS NOT NULL;

CREATE INDEX idx_handoff_team_seq ON agent_board_entries(team_id, kind, seq DESC);

CREATE TABLE agent_board_usage (
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  day TEXT NOT NULL,
  posts INTEGER NOT NULL DEFAULT 0,
  bytes INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (project_id, day)
);

CREATE INDEX idx_agent_board_usage_day ON agent_board_usage(day);

CREATE TRIGGER agent_board_usage_cap_insert BEFORE INSERT ON agent_board_usage
BEGIN
  SELECT RAISE(ABORT, 'cap:board_posts_day')
  WHERE NEW.posts > (SELECT c.posts_per_day FROM projects p JOIN agent_board_caps c ON c.board_kind = p.board_kind
    WHERE p.id = NEW.project_id);
  SELECT RAISE(ABORT, 'cap:board_bytes_day')
  WHERE NEW.bytes > (SELECT c.bytes_per_day FROM projects p JOIN agent_board_caps c ON c.board_kind = p.board_kind
    WHERE p.id = NEW.project_id);
END;

CREATE TRIGGER agent_board_usage_cap_update BEFORE UPDATE ON agent_board_usage
BEGIN
  SELECT RAISE(ABORT, 'cap:board_posts_day')
  WHERE NEW.posts > (SELECT c.posts_per_day FROM projects p JOIN agent_board_caps c ON c.board_kind = p.board_kind
    WHERE p.id = NEW.project_id);
  SELECT RAISE(ABORT, 'cap:board_bytes_day')
  WHERE NEW.bytes > (SELECT c.bytes_per_day FROM projects p JOIN agent_board_caps c ON c.board_kind = p.board_kind
    WHERE p.id = NEW.project_id);
END;

CREATE TABLE agent_project_grants (
  agent_id TEXT NOT NULL REFERENCES agent_identities(id) ON DELETE CASCADE,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  permission TEXT NOT NULL CHECK (permission IN ('read', 'write')),
  created_by_user_id TEXT NOT NULL REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (agent_id, project_id)
);

CREATE INDEX idx_agent_project_grants_project ON agent_project_grants(project_id, permission);

CREATE TRIGGER agent_grants_not_person BEFORE INSERT ON agent_project_grants
WHEN (SELECT kind FROM agent_identities WHERE id = NEW.agent_id) = 'person'
BEGIN
  SELECT RAISE(ABORT, 'person identities cannot hold project grants');
END;

CREATE TABLE artifacts (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id),
  title TEXT NOT NULL,
  description TEXT,
  favicon TEXT NOT NULL,
  source_path TEXT,
  source_kind TEXT NOT NULL DEFAULT 'html' CHECK (source_kind IN ('html', 'markdown')),
  visibility TEXT NOT NULL DEFAULT 'private' CHECK (visibility IN ('private', 'public')),
  shared_version INTEGER,
  current_version INTEGER NOT NULL DEFAULT 1,
  capabilities TEXT,
  instance_session_id TEXT,
  instance_project TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
, role TEXT NOT NULL DEFAULT 'page'
  CHECK (role IN ('page', 'widget')), design_system TEXT, team_id TEXT REFERENCES teams(id), project_id TEXT REFERENCES projects(id), sharing TEXT NOT NULL DEFAULT 'private' CHECK (sharing IN ('private','shared')));

CREATE INDEX idx_artifacts_project_id ON artifacts(project_id);

CREATE INDEX idx_artifacts_team_channel_updated ON artifacts(team_id, project_id, updated_at);

CREATE INDEX idx_artifacts_team_id ON artifacts(team_id);

CREATE INDEX idx_artifacts_user_updated ON artifacts(user_id, updated_at DESC);

CREATE TRIGGER artifacts_not_in_work_board BEFORE INSERT ON artifacts
WHEN NEW.project_id IS NOT NULL AND (SELECT board_kind FROM projects WHERE id = NEW.project_id) = 'work'
BEGIN
  SELECT RAISE(ABORT, 'work boards hold board posts only');
END;

CREATE TRIGGER artifacts_not_moved_to_work_board BEFORE UPDATE OF project_id ON artifacts
WHEN NEW.project_id IS NOT NULL AND (SELECT board_kind FROM projects WHERE id = NEW.project_id) = 'work'
BEGIN
  SELECT RAISE(ABORT, 'work boards hold board posts only');
END;

CREATE TRIGGER private_artifact_no_referenced_move BEFORE UPDATE OF team_id ON artifacts
WHEN OLD.team_id IS NOT NULL AND NEW.team_id IS NOT OLD.team_id
  AND EXISTS (SELECT 1 FROM message_blocks WHERE artifact_id=OLD.id)
BEGIN SELECT RAISE(ABORT, 'A referenced artifact cannot change teams'); END;

CREATE TRIGGER private_artifact_no_referenced_unpublish BEFORE UPDATE OF sharing ON artifacts
WHEN NEW.sharing='private' AND OLD.sharing='shared'
  AND EXISTS (SELECT 1 FROM message_blocks WHERE artifact_id=OLD.id)
BEGIN SELECT RAISE(ABORT, 'A referenced artifact must remain shared'); END;

CREATE TRIGGER team_governance_artifact_audience BEFORE UPDATE OF sharing,team_id ON artifacts
WHEN (NEW.sharing IS NOT OLD.sharing OR NEW.team_id IS NOT OLD.team_id)
 AND EXISTS(SELECT 1 FROM team_governance WHERE team_id IN (OLD.team_id,NEW.team_id))
BEGIN SELECT RAISE(ABORT, 'Use governed document access policies'); END;

CREATE TRIGGER team_governance_artifact_visibility BEFORE UPDATE OF visibility ON artifacts
WHEN NEW.visibility!='private' AND EXISTS(SELECT 1 FROM team_governance WHERE team_id=NEW.team_id)
BEGIN SELECT RAISE(ABORT, 'Governed resources cannot be public'); END;

CREATE TRIGGER team_governance_private_artifact_insert BEFORE INSERT ON artifacts
WHEN (NEW.sharing='shared' OR NEW.visibility!='private') AND EXISTS(SELECT 1 FROM team_governance WHERE team_id=NEW.team_id)
BEGIN SELECT RAISE(ABORT, 'Governed resources require an explicit access policy'); END;

CREATE TRIGGER team_governance_referenced_artifact_delete BEFORE DELETE ON artifacts
WHEN EXISTS(SELECT 1 FROM team_governance WHERE team_id=OLD.team_id)
 AND EXISTS(SELECT 1 FROM message_blocks WHERE artifact_id=OLD.id)
BEGIN SELECT RAISE(ABORT, 'Remove referencing posts before deleting a governed artifact'); END;

CREATE TABLE oauth_codes (
  code_hash TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  client_id TEXT NOT NULL,
  redirect_uri TEXT NOT NULL,
  scope TEXT NOT NULL,
  code_challenge TEXT NOT NULL,
  expires_at INTEGER NOT NULL
, team_id TEXT REFERENCES teams(id) ON DELETE CASCADE, agent_id TEXT REFERENCES agent_identities(id) ON DELETE CASCADE, connection_id TEXT REFERENCES oauth_connections(id) ON DELETE CASCADE);

CREATE INDEX idx_oauth_code_expiry ON oauth_codes(expires_at);

CREATE TABLE oauth_refresh (
  token_hash TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  client_id TEXT NOT NULL,
  scope TEXT NOT NULL,
  expires_at INTEGER NOT NULL
, team_id TEXT REFERENCES teams(id) ON DELETE CASCADE, agent_id TEXT REFERENCES agent_identities(id) ON DELETE CASCADE, connection_id TEXT REFERENCES oauth_connections(id) ON DELETE CASCADE);

CREATE INDEX idx_oauth_refresh_expiry ON oauth_refresh(expires_at);

CREATE INDEX idx_oauth_refresh_agent ON oauth_refresh(agent_id);

CREATE INDEX idx_oauth_refresh_connection ON oauth_refresh(connection_id);

CREATE TABLE events (
  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  id TEXT NOT NULL UNIQUE,
  team_id TEXT REFERENCES teams(id) ON DELETE CASCADE,
  owner_user_id TEXT REFERENCES users(id) ON DELETE CASCADE,
  type TEXT NOT NULL,
  actor_ref TEXT,
  subject_ref TEXT,
  project_id TEXT REFERENCES projects(id) ON DELETE SET NULL,
  payload TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(payload)),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  dispatched_at TEXT,
  CHECK ((team_id IS NOT NULL) + (owner_user_id IS NOT NULL) = 1)
);

CREATE INDEX idx_events_created ON events(created_at);

CREATE INDEX idx_events_owner_seq ON events(owner_user_id, seq) WHERE owner_user_id IS NOT NULL;

CREATE INDEX idx_events_subject ON events(team_id, subject_ref, seq);

CREATE INDEX idx_events_team_seq ON events(team_id, seq);

CREATE INDEX idx_events_undispatched ON events(created_at) WHERE dispatched_at IS NULL;

CREATE TRIGGER events_count_usage AFTER INSERT ON events
WHEN NEW.team_id IS NOT NULL
BEGIN
  INSERT INTO event_usage (team_id, day, events) VALUES (NEW.team_id, date('now'), 1)
    ON CONFLICT(team_id, day) DO UPDATE SET events = events + 1;
END;

CREATE TABLE member_agent_scopes (
  team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  granted_by_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (team_id, user_id, project_id)
);

CREATE INDEX idx_member_agent_scopes_project ON member_agent_scopes(project_id);

CREATE TRIGGER member_agent_scopes_not_work BEFORE INSERT ON member_agent_scopes
WHEN (SELECT board_kind FROM projects WHERE id = NEW.project_id) = 'work'
BEGIN
  SELECT RAISE(IGNORE);
END;

CREATE TABLE member_onboarding (
  team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  handover_project_id TEXT REFERENCES projects(id) ON DELETE SET NULL,
  locale TEXT NOT NULL DEFAULT 'en' CHECK (locale IN ('en', 'ru')),
  instructions_copied_at TEXT,
  dismissed_at TEXT,
  updated_at TEXT NOT NULL DEFAULT (datetime('now')), help_opened_at TEXT, welcomed_at TEXT, intro_seen_at TEXT,
  PRIMARY KEY (team_id, user_id)
);

CREATE TABLE messages (
  id TEXT PRIMARY KEY,
  type TEXT NOT NULL CHECK(type IN ('message', 'question', 'status', 'document')),
  title TEXT NOT NULL,
  body TEXT,
  doc_key TEXT,
  priority TEXT NOT NULL DEFAULT 'normal',
  instance_model TEXT NOT NULL,
  instance_session_id TEXT NOT NULL,
  instance_project TEXT NOT NULL,
  instance_source TEXT NOT NULL,
  reply TEXT,
  replied_at TEXT,
  read INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, public INTEGER NOT NULL DEFAULT 0, archived_at TEXT, doc_slug TEXT, doc_version INTEGER, is_latest INTEGER NOT NULL DEFAULT 1, user_id TEXT REFERENCES users(id), last_poll_at TEXT, read_at TEXT, source_url TEXT, dismiss_action TEXT, expires_at TIMESTAMP, pinned INTEGER NOT NULL DEFAULT 0, enhance_status TEXT, enhance_level TEXT, enhance_error TEXT, design_system TEXT, interactive INTEGER NOT NULL DEFAULT 0, team_id TEXT REFERENCES teams(id), project_id TEXT REFERENCES projects(id), doc_kind TEXT NOT NULL DEFAULT 'doc'
  CHECK (doc_kind IN ('doc', 'decision_memo', 'meeting_note', 'spec', 'runbook')), doc_size INTEGER NOT NULL DEFAULT 0, source_size INTEGER NOT NULL DEFAULT 0, replied_by_user_id TEXT REFERENCES users(id), replied_via TEXT, sharing TEXT NOT NULL DEFAULT 'private' CHECK (sharing IN ('private','shared')), sharing_explicit INTEGER NOT NULL DEFAULT 0 CHECK(sharing_explicit IN (0,1)));

CREATE INDEX idx_messages_archived ON messages(archived_at);

CREATE INDEX idx_messages_created ON messages(created_at DESC);

CREATE INDEX idx_messages_doc_kind ON messages(doc_kind);

CREATE INDEX idx_messages_doc_slug ON messages(doc_slug);

CREATE INDEX idx_messages_expires ON messages (expires_at) WHERE expires_at IS NOT NULL;

CREATE INDEX idx_messages_last_poll ON messages(last_poll_at);

CREATE INDEX idx_messages_priority ON messages(priority);

CREATE INDEX idx_messages_project_id ON messages(project_id);

CREATE INDEX idx_messages_read ON messages(read);

CREATE INDEX idx_messages_team_channel_created ON messages(team_id, project_id, created_at);

CREATE INDEX idx_messages_team_id ON messages(team_id);

CREATE INDEX idx_messages_type ON messages(type);

CREATE INDEX idx_messages_user_id ON messages(user_id);

CREATE TRIGGER messages_not_in_work_board BEFORE INSERT ON messages
WHEN NEW.project_id IS NOT NULL AND (SELECT board_kind FROM projects WHERE id = NEW.project_id) = 'work'
BEGIN
  SELECT RAISE(ABORT, 'work boards hold board posts only');
END;

CREATE TRIGGER messages_not_moved_to_work_board BEFORE UPDATE OF project_id ON messages
WHEN NEW.project_id IS NOT NULL AND (SELECT board_kind FROM projects WHERE id = NEW.project_id) = 'work'
BEGIN
  SELECT RAISE(ABORT, 'work boards hold board posts only');
END;

CREATE TRIGGER team_governance_message_audience BEFORE UPDATE OF sharing,team_id,type ON messages
WHEN (OLD.type='document' OR NEW.type='document')
 AND (NEW.sharing IS NOT OLD.sharing OR NEW.team_id IS NOT OLD.team_id OR NEW.type IS NOT OLD.type)
 AND EXISTS(SELECT 1 FROM team_governance WHERE team_id IN (OLD.team_id,NEW.team_id))
BEGIN SELECT RAISE(ABORT, 'Use governed document access policies'); END;

CREATE TRIGGER team_governance_private_message_insert BEFORE INSERT ON messages
WHEN NEW.type='document' AND NEW.sharing='shared' AND EXISTS(SELECT 1 FROM team_governance WHERE team_id=NEW.team_id)
 AND (COALESCE(NEW.doc_version,1)<=1 OR NOT EXISTS(
 SELECT 1 FROM messages prior WHERE prior.team_id=NEW.team_id AND prior.type='document'
 AND COALESCE(prior.doc_slug,prior.id)=COALESCE(NEW.doc_slug,NEW.id)
 AND prior.sharing='shared' AND COALESCE(prior.doc_version,1)<NEW.doc_version))
BEGIN SELECT RAISE(ABORT, 'Governed resources require an explicit access policy'); END;

CREATE TABLE ops_runbooks (
  id TEXT PRIMARY KEY,
  team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  project_id TEXT REFERENCES projects(id) ON DELETE SET NULL,
  title TEXT NOT NULL,
  summary TEXT NOT NULL DEFAULT '',
  owner_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published', 'archived')),
  current_version INTEGER NOT NULL DEFAULT 1 CHECK (current_version > 0),
  created_by_user_id TEXT NOT NULL REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX idx_ops_runbooks_team_status ON ops_runbooks(team_id, status, updated_at DESC);

CREATE TABLE project_management_policies (
  project_id TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,
  team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  enabled INTEGER NOT NULL CHECK (enabled IN (0, 1)),
  body TEXT NOT NULL,
  version INTEGER NOT NULL CHECK (version > 0),
  updated_by_user_id TEXT NOT NULL REFERENCES users(id),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE project_management_policy_revisions (
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  version INTEGER NOT NULL,
  enabled INTEGER NOT NULL CHECK (enabled IN (0, 1)),
  body TEXT NOT NULL,
  updated_by_user_id TEXT NOT NULL REFERENCES users(id),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (project_id, version)
);

CREATE TABLE resource_comments (
  id TEXT PRIMARY KEY,
  team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  project_id TEXT REFERENCES projects(id) ON DELETE SET NULL,
  resource_type TEXT NOT NULL CHECK (resource_type IN ('message', 'artifact', 'document', 'decision_memo')),
  resource_id TEXT NOT NULL,
  parent_id TEXT REFERENCES resource_comments(id) ON DELETE CASCADE,
  body TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'resolved')),
  author_user_id TEXT NOT NULL REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX idx_resource_comments_project
  ON resource_comments(project_id, created_at);

CREATE INDEX idx_resource_comments_team_resource
  ON resource_comments(team_id, resource_type, resource_id, created_at);

CREATE TABLE team_access_role_members (
  team_id TEXT NOT NULL,
  role_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  PRIMARY KEY(team_id,role_id,user_id),
  FOREIGN KEY(team_id,role_id) REFERENCES team_access_roles(team_id,id) ON DELETE CASCADE,
  FOREIGN KEY(team_id,user_id) REFERENCES team_memberships(team_id,user_id) ON DELETE CASCADE
);

CREATE TABLE agent_board_closures (
  entry_id TEXT PRIMARY KEY REFERENCES agent_board_entries(id) ON DELETE CASCADE,
  team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  reason TEXT NOT NULL CHECK (reason IN ('resolved', 'read', 'audience_read', 'expired')),
  -- agent:<agent_id> or user:<user_id>; NULL when the server closed it.
  closed_by_ref TEXT,
  closed_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX idx_agent_board_closures_team ON agent_board_closures(team_id, closed_at);

CREATE TABLE agent_board_digest_ai_backoff (
  entry_id TEXT PRIMARY KEY REFERENCES agent_board_entries(id) ON DELETE CASCADE,
  team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  failure_count INTEGER NOT NULL DEFAULT 1 CHECK (failure_count > 0),
  retry_after TEXT NOT NULL,
  reason TEXT NOT NULL CHECK (reason IN ('split_hint', 'ai_failure'))
);

CREATE INDEX idx_agent_board_digest_ai_backoff_team_retry
  ON agent_board_digest_ai_backoff(team_id, retry_after);

CREATE TABLE agent_board_digest_restores (
  entry_id TEXT PRIMARY KEY REFERENCES agent_board_entries(id) ON DELETE CASCADE,
  team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  restored_by_user_id TEXT NOT NULL REFERENCES users(id),
  restored_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE agent_board_documents (
  entry_id TEXT PRIMARY KEY REFERENCES agent_board_entries(id) ON DELETE CASCADE,
  message_id TEXT NOT NULL UNIQUE REFERENCES messages(id) ON DELETE CASCADE,
  original_reference TEXT,
  body_hash TEXT NOT NULL,
  authorized INTEGER NOT NULL CHECK (authorized = 1)
);

CREATE TABLE "agent_board_moderation" (
  entry_id TEXT PRIMARY KEY REFERENCES agent_board_entries(id) ON DELETE CASCADE,
  action TEXT NOT NULL DEFAULT 'tombstone' CHECK (action = 'tombstone'),
  reason TEXT NOT NULL,
  actor_user_id TEXT REFERENCES users(id),
  actor_kind TEXT NOT NULL DEFAULT 'person' CHECK (actor_kind IN ('person', 'system')),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  CHECK ((actor_kind = 'system' AND actor_user_id IS NULL) OR
         (actor_kind = 'person' AND actor_user_id IS NOT NULL))
);

CREATE TABLE agent_board_reads (
  entry_id TEXT NOT NULL REFERENCES agent_board_entries(id) ON DELETE CASCADE,
  reader_ref TEXT NOT NULL,
  read_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (entry_id, reader_ref)
);

CREATE INDEX idx_agent_board_reads_reader ON agent_board_reads(reader_ref, entry_id);

CREATE TABLE "agent_board_trash" (
  entry_id TEXT PRIMARY KEY REFERENCES agent_board_entries(id) ON DELETE CASCADE,
  team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  actor_user_id TEXT REFERENCES users(id),
  actor_kind TEXT NOT NULL DEFAULT 'person' CHECK (actor_kind IN ('person', 'system')),
  digest_id TEXT,
  trashed_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  purge_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '+30 days')),
  CHECK ((actor_kind = 'system' AND actor_user_id IS NULL AND digest_id IS NOT NULL) OR
         (actor_kind = 'person' AND actor_user_id IS NOT NULL AND digest_id IS NULL))
);

CREATE INDEX idx_agent_board_trash_digest ON agent_board_trash(digest_id);

CREATE INDEX idx_agent_board_trash_purge ON agent_board_trash(purge_at, entry_id);

CREATE INDEX idx_agent_board_trash_team_time ON agent_board_trash(team_id, trashed_at DESC, entry_id);

CREATE TRIGGER agent_board_trash_hide AFTER INSERT ON agent_board_trash
BEGIN
  INSERT INTO agent_board_moderation(entry_id, reason, actor_user_id, actor_kind)
  VALUES (NEW.entry_id, CASE WHEN NEW.actor_kind = 'system' THEN 'Moved to Trash after the board summary' ELSE 'Moved to Trash' END,
          NEW.actor_user_id, NEW.actor_kind);
END;

CREATE TABLE artifact_storage (
  artifact_id TEXT NOT NULL REFERENCES artifacts(id),
  scope TEXT NOT NULL,
  key TEXT NOT NULL,
  value TEXT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (artifact_id, scope, key)
);

CREATE TABLE artifact_versions (
  artifact_id TEXT NOT NULL REFERENCES artifacts(id),
  version INTEGER NOT NULL,
  label TEXT,
  r2_key TEXT NOT NULL,
  size INTEGER NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  created_by_session TEXT, source_size INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (artifact_id, version)
);

CREATE TABLE commute_briefings (
  source_message_id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  transcript_key TEXT NOT NULL,
  audio_key TEXT,
  metadata_key TEXT,
  provider TEXT NOT NULL DEFAULT 'openai',
  voice TEXT,
  model TEXT,
  minutes INTEGER NOT NULL DEFAULT 3,
  status TEXT NOT NULL DEFAULT 'pending',
  error TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')), source_type TEXT NOT NULL DEFAULT 'document', playlist_doc_ids TEXT, transcript_size INTEGER NOT NULL DEFAULT 0, audio_size INTEGER NOT NULL DEFAULT 0, metadata_size INTEGER NOT NULL DEFAULT 0,
  FOREIGN KEY (source_message_id) REFERENCES messages(id)
);

CREATE INDEX idx_commute_briefings_created
  ON commute_briefings(created_at DESC);

CREATE INDEX idx_commute_briefings_source_created
  ON commute_briefings(source_type, created_at DESC);

CREATE TABLE commute_playlist_items (
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (user_id, message_id)
);

CREATE INDEX idx_playlist_user_pos
  ON commute_playlist_items(user_id, position);

CREATE TABLE deferred_actions (
  id TEXT PRIMARY KEY,
  team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  created_by_user_id TEXT NOT NULL REFERENCES users(id),
  trigger_type TEXT NOT NULL,
  trigger_match TEXT NOT NULL CHECK (json_valid(trigger_match)),
  action TEXT NOT NULL CHECK (json_valid(action)),
  status TEXT NOT NULL DEFAULT 'armed' CHECK (status IN ('armed','fired','failed','cancelled','expired')),
  fires_at TEXT,
  expires_at TEXT NOT NULL,
  armed_after_seq INTEGER NOT NULL DEFAULT 0,
  fired_event_id TEXT REFERENCES events(id) ON DELETE SET NULL,
  fired_at TEXT,
  error TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE INDEX idx_deferred_creator ON deferred_actions(created_by_user_id, status);

CREATE INDEX idx_deferred_expiry ON deferred_actions(status, expires_at);

CREATE INDEX idx_deferred_trigger ON deferred_actions(team_id, trigger_type, status);

CREATE TABLE handoff_archives (
  entry_id TEXT NOT NULL REFERENCES agent_board_entries(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  archived_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (entry_id, user_id)
);

CREATE TABLE handoff_reads (
  entry_id TEXT NOT NULL REFERENCES agent_board_entries(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  read_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (entry_id, user_id)
);

CREATE TABLE message_blocks (
  message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('markdown', 'artifact')),
  markdown TEXT,
  artifact_id TEXT,
  artifact_version INTEGER,
  label TEXT,
  producer TEXT,
  producer_action TEXT,
  summary TEXT,
  collapsed INTEGER NOT NULL DEFAULT 0,
  artifact_title_snapshot TEXT,
  artifact_favicon_snapshot TEXT,
  PRIMARY KEY (message_id, position),
  CHECK (
    (kind = 'markdown' AND markdown IS NOT NULL
      AND artifact_id IS NULL AND artifact_version IS NULL)
    OR
    (kind = 'artifact' AND markdown IS NULL
      AND artifact_id IS NOT NULL AND artifact_version IS NOT NULL)
  )
);

CREATE INDEX idx_message_blocks_artifact
  ON message_blocks(artifact_id, artifact_version);

CREATE TRIGGER message_artifact_pin_insert
BEFORE INSERT ON message_blocks
WHEN NEW.kind = 'artifact' AND NOT EXISTS (
  SELECT 1 FROM artifact_versions
  WHERE artifact_id = NEW.artifact_id AND version = NEW.artifact_version
)
BEGIN
  SELECT RAISE(ABORT, 'artifact block version unavailable');
END;

CREATE TRIGGER message_artifact_pin_update
BEFORE UPDATE OF message_id,kind,artifact_id,artifact_version ON message_blocks
WHEN NEW.kind = 'artifact' AND NOT EXISTS (
  SELECT 1 FROM artifact_versions
  WHERE artifact_id = NEW.artifact_id AND version = NEW.artifact_version
)
BEGIN
  SELECT RAISE(ABORT, 'artifact block version unavailable');
END;

CREATE TRIGGER private_artifact_no_team_embed BEFORE INSERT ON message_blocks
WHEN NEW.artifact_id IS NOT NULL AND EXISTS (
  SELECT 1 FROM messages m JOIN artifacts a ON a.id=NEW.artifact_id
  WHERE m.id=NEW.message_id AND m.team_id IS NOT NULL
    AND (a.team_id IS NOT m.team_id OR a.sharing!='shared'))
BEGIN SELECT RAISE(ABORT, 'Artifact audience changed; publish it to the team before embedding'); END;

CREATE TRIGGER team_governance_no_policy_embed BEFORE INSERT ON message_blocks
WHEN NEW.artifact_id IS NOT NULL AND EXISTS(
  SELECT 1 FROM artifacts a JOIN team_governance g ON g.team_id=a.team_id WHERE a.id=NEW.artifact_id)
BEGIN SELECT RAISE(ABORT, 'Governed artifact cannot be embedded'); END;

CREATE TRIGGER team_governance_no_policy_embed_update BEFORE UPDATE OF artifact_id ON message_blocks
WHEN NEW.artifact_id IS NOT NULL AND EXISTS(
  SELECT 1 FROM artifacts a JOIN team_governance g ON g.team_id=a.team_id WHERE a.id=NEW.artifact_id)
BEGIN SELECT RAISE(ABORT, 'Governed artifact cannot be embedded'); END;

CREATE TABLE message_user_state (
  message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  read INTEGER NOT NULL DEFAULT 0,
  read_at TEXT,
  archived_at TEXT,
  dismiss_action TEXT CHECK (dismiss_action IN ('archive', 'delete')),
  pinned INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (message_id, user_id)
);

CREATE INDEX idx_message_user_state_user ON message_user_state(user_id, archived_at);

CREATE TABLE inbox_items (
  id TEXT PRIMARY KEY,
  team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('secret_share','event','mention','system')),
  event_id TEXT REFERENCES events(id) ON DELETE SET NULL,
  share_id TEXT,
  deferred_action_id TEXT REFERENCES deferred_actions(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  body TEXT,
  link TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  read_at TEXT,
  dismissed_at TEXT,
  tombstoned_at TEXT
);

CREATE UNIQUE INDEX idx_inbox_deferred_user ON inbox_items(user_id, deferred_action_id)
  WHERE deferred_action_id IS NOT NULL;

CREATE UNIQUE INDEX idx_inbox_event_user ON inbox_items(user_id, event_id, kind)
  WHERE event_id IS NOT NULL AND deferred_action_id IS NULL;

CREATE INDEX idx_inbox_user ON inbox_items(user_id, dismissed_at, created_at DESC);
